    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xA2D90F7109447D6DULL + 0x8F65F90A933B25D6ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xAE63A3B8103BF55DULL + 0xED49F0110EAF05DCULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0xDA27C1874D2B25AFULL + 0x8A6FBEAD246C35D5ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseB(pNonce * 0xBA28B3FD6019DB69ULL + 0xA0668C3F870F6EF3ULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xAB006DB6E1F7FC85ULL + 0x9604750F00945378ULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0xED17DF8EBF3DC55FULL + 0xEF3D5F3378BE43BCULL);
