    const std::uint64_t aNonceWordI = TwistMix64::DiffuseA(pNonce * 0xA0B1DDD71182BAF1ULL + 0xC791BD67230E3C2AULL);
    const std::uint64_t aNonceWordJ = TwistMix64::DiffuseC(pNonce * 0xCFDA603A518F351DULL + 0xB773FA1241E4AAE7ULL);
    const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0xC9D397A91BD560A1ULL + 0xB1FD3DC2B31CC03EULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0x9AB4AC3E4DE58E03ULL + 0xDC61C93E363BD623ULL);
