            aCross = TwistMix64::DiffuseC(((aCross ^ aSeedDomainWordCross) ^ aNonceWordG));
            //
            aScatter = (RotL64(aCross, 23U) + RotL64(aPrevious, 38U)) ^ (RotL64(aCarry, 53U) + RotL64(aIngress, 11U));
            aScatter = TwistMix64::DiffuseA(((aScatter ^ aSeedDomainWordScatter) ^ aNonceWordF));
            //
            aOrbiterJ = (aWandererB + RotL64(aIngress, 13U)) + 0x43315507815CD77FULL;
            aOrbiterH = ((aWandererG + RotL64(aScatter, 11U)) + RotL64(aCarry, 5U)) + 0xCD8D4E96F6A97D62ULL;
            aOrbiterB = (((aWandererI + RotL64(aPrevious, 23U)) + 0x709210183D1F4594ULL) + aOASaltD[((aIndex + 23U)) & S_SALT1]) + aNonceWordA;
            aOrbiterG = ((aWandererC + RotL64(aCross, 29U)) + 0xA0C8C456C4A1C15CULL) + aNonceWordP;
            aOrbiterE = (((aWandererK + RotL64(aIngress, 51U)) + 0x859ACD8819119952ULL) + aOASaltB[((aIndex + 344U)) & S_SALT1]) + aNonceWordL;
