            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0x2E79826F5D15B761ULL) + aOUSaltH[((aIndex + 425U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x6E2686D716393FB8ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x781F3B525EAF9335ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x14E86AA1F4447E6DULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0xF3C1F6BDAF179105ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x96EABB0C537AAC85ULL), 11U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x4326E9BA58C175EDULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0xCFA2496DEDEB1528ULL) ^ aOUSaltG[((aIndex + 16U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x87F591F6D3098F99ULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x9FD129C74ADD8DE9ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0x95A860F676C38C58ULL) ^ aOUSaltF[(((511U - aIndex) + 60U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xE42425E8AAFD18E1ULL), 43U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0x0AB51E412A6AAEBEULL) + aNonceWordC;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x46302C8A8EC14AC3ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1EA7D79653562633ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x9033B5850C3A8D88ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0xBD2BE09516623F43ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0CABAA98CC5CEFB7ULL), 37U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0xAB7BAA0D7CAAA94CULL) + aOUSaltA[(((511U - aIndex) + 4U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0xC420CBD11293BB16ULL) ^ aOUSaltE[((aIndex + 327U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xDF24A43C810CA5E5ULL), 23U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x1EE35D791F9A4C51ULL;
