            aIngress = aIngress + RotL64(aOrbiterF, 39U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererB = aWandererB + ((((RotL64(aScatter, 40U) + aOrbiterI) + RotL64(aOrbiterD, 48U)) + aNonceWordI) + aWUSaltH[(((511U - aIndex) + 493U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 5U) + aOrbiterC) + RotL64(aOrbiterF, 57U));
