            aCross = RotL64(aSource[((S_BLOCK1 - aIndex + 10236U)) & S_BLOCK1], 21U) ^ RotL64(aNonceLane[((S_BLOCK1 - aIndex + 9968U)) & S_BLOCK1], 56U);
            aCross = TwistMix64::DiffuseA(((aCross ^ aSeedDomainWordCross) ^ aNonceWordM));
            //
            aScatter = (RotL64(aCross, 3U) + RotL64(aIngress, 41U)) ^ (RotL64(aPrevious, 53U) ^ RotL64(aCarry, 20U));
            aScatter = TwistMix64::DiffuseB(((aScatter ^ aSeedDomainWordScatter) ^ aNonceWordK));
            //
            aOrbiterJ = (aWandererI + RotL64(aScatter, 27U)) + 0x3550BBE4E1D61E06ULL;
            aOrbiterC = (aWandererC + RotL64(aPrevious, 48U)) + 0x145B6758333496C6ULL;
            aOrbiterE = ((aWandererD + RotL64(aCross, 5U)) + RotL64(aCarry, 43U)) + 0xB769CF5ED4F9A030ULL;
            aOrbiterK = (aWandererK + RotL64(aIngress, 53U)) + 0xC580ABE821C70694ULL;
            aOrbiterD = (aWandererJ + RotL64(aScatter, 37U)) + 0xC36CD721AEAB303EULL;
            aOrbiterH = ((aWandererE + RotL64(aPrevious, 21U)) + 0xB1E2A0FECCB5A590ULL) + aNonceWordE;
            aOrbiterB = (((aWandererH + RotL64(aCross, 24U)) + RotL64(aCarry, 47U)) + 0x5EE4094832681DB8ULL) + aOASaltB[((aIndex + 244U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aIngress, 43U)) + 0x41E5AE1AD07D11E7ULL) + aOASaltD[(((511U - aIndex) + 343U)) & S_SALT1];
            aOrbiterF = (aWandererA + RotL64(aScatter, 19U)) + 0x48410E1715E38BA9ULL;
            aOrbiterG = ((aWandererB + RotL64(aPrevious, 57U)) + RotL64(aCarry, 23U)) + 0xE57A783960B2D6C8ULL;
