            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x5A4CE10DB2782442ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x64FE063D27EF3B8CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x3A9A38487C4E52D3ULL), 43U);
            //
            aOrbiterB = (((aOrbiterB + aOrbiterA) + 0x1729960E664345C9ULL) + aOUSaltD[((aIndex + 502U)) & S_SALT1]) + aNonceWordH;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0xF40F64FE41A34CF7ULL) ^ aOUSaltC[((aIndex + 469U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x69E7074F76E58957ULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xC36448E08B3F7464ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0xFD0EC2AE2EF0A719ULL) ^ aNonceWordC;
            aOrbiterG = RotL64((aOrbiterG * 0x9F05DE9298DAE517ULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xF3F7965D72732E69ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x43F4A9DEEE4731CAULL;
            aOrbiterC = RotL64((aOrbiterC * 0x33C2098FB48889E1ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x106ECCF1A12C8D93ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xD88D90245AF3787EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x719BA1E8EC6B4585ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x6478541ABCB11122ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x47F49B27A9212AD8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xDE308EC9DD2E9971ULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x22CC946888533F43ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x6704F1A048D8DEB0ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x706EF3E79049D77DULL), 51U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x0A4FBA1240E8F129ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0x47C9D89BF7A951E1ULL) ^ aOUSaltE[(((511U - aIndex) + 423U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x37E8E5829C0CE045ULL), 11U);
