            aWandererF = aWandererF + (((RotL64(aPrevious, 41U) + RotL64(aOrbiterB, 39U)) + aOrbiterF) + aWUSaltC[((aIndex + 43U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aCross, 39U) + aOrbiterG) + RotL64(aOrbiterI, 23U));
            aWandererH = aWandererH + (((RotL64(aIngress, 37U) + aOrbiterE) + RotL64(aOrbiterC, 5U)) + RotL64(aCarry, 35U));
