            aOrbiterC = ((aWandererI + RotL64(aScatter, 50U)) + 0x079B2C373E7CB2D9ULL) + aOASaltD[((aIndex + 242U)) & S_SALT1];
            aOrbiterF = (aWandererH + RotL64(aPrevious, 5U)) + 0xDDA0D91BD2846A6BULL;
            aOrbiterI = (aWandererE + RotL64(aCross, 35U)) + 0x814CA50EE4825A77ULL;
            aOrbiterD = ((aWandererA + RotL64(aIngress, 21U)) + RotL64(aCarry, 5U)) + 0xE7F4DE9CF159F8C6ULL;
