            aOrbiterK = (aOrbiterK + aOrbiterC) + 0xC0E4F7D5F7616FCFULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xA9E37EFAF6456A90ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xCCD0963853150E15ULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x30F6B37D2D2AD14AULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x85BD0516EE24F926ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x4F4581B4ABC3F427ULL), 39U);
