            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x9BCCF94A7E640F81ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x16614A0C7A0EB5E8ULL) ^ aOUSaltG[((aIndex + 295U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x1B016AC5571B0CD7ULL), 43U);
