            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x5CC52E6D4F471B71ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xDB78F3180C8FD5C2ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD319E2D8E13625A9ULL), 47U);
