            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 30041U)) & S_BLOCK1], 53U) ^ RotL64(aKineticLaneD[((S_BLOCK1 - aIndex + 26028U)) & S_BLOCK1], 19U));
