            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterK = (aWandererA + RotL64(aCross, 13U)) + 0x0878F9B69CB4C85AULL;
            aOrbiterJ = ((aWandererB + RotL64(aIngress, 54U)) + 0x23A336463778A6FBULL) + aOASaltH[((aIndex + 108U)) & S_SALT1];
            aOrbiterA = (aWandererD + RotL64(aScatter, 51U)) + 0x76F4B8F40B33B435ULL;
            aOrbiterC = ((aWandererK + RotL64(aPrevious, 47U)) + RotL64(aCarry, 13U)) + 0x5A541F8DF994E60FULL;
            aOrbiterB = ((aWandererF + RotL64(aCross, 19U)) + 0xF01E0E0B7F7A0739ULL) + aOASaltF[(((511U - aIndex) + 225U)) & S_SALT1];
            aOrbiterD = (aWandererE + RotL64(aIngress, 27U)) + 0xC59E529A915121D9ULL;
            aOrbiterE = ((aWandererJ + RotL64(aScatter, 5U)) + 0xDBC55830983FA3B2ULL) + aOASaltD[((aIndex + 383U)) & S_SALT1];
            aOrbiterH = ((aWandererC + RotL64(aPrevious, 35U)) + RotL64(aCarry, 47U)) + 0x0892CDE67ED74A29ULL;
            aOrbiterI = ((aWandererI + RotL64(aCross, 10U)) + 0xEE5232B42C509EECULL) + aOASaltB[(((511U - aIndex) + 125U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aIngress, 41U)) + 0xA88141EB409C84F7ULL;
            aOrbiterF = (((aWandererH + RotL64(aScatter, 39U)) + RotL64(aCarry, 5U)) + 0x7AA7DBBA7112BF7FULL) + aOASaltG[((aIndex + 138U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xA0D12E7212F0CD2EULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x50A1C8650B1ABB15ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x4F72F426FBDB9CBFULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0xEADE2CEF8F989C2CULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0xEE6C27D43E0F7901ULL) ^ aOUSaltA[((aIndex + 283U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x91463E95244B44C9ULL), 23U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x3BF6721BC6384843ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xC71D687680ACA8C5ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xDB798708172D14F5ULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xD714A39054885627ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xB3F4FE3A1B2E34BBULL;
            aOrbiterK = RotL64((aOrbiterK * 0x838D99551574D6BBULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x99076C86CB5F4CD6ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x930D07C12E92072DULL;
            aOrbiterC = RotL64((aOrbiterC * 0x26F9757F78D04123ULL), 53U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xCC6B1D8263CA3A91ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xF41D73384A765E7EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xB19283B1085A1513ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x1842641A21BB3D5FULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0xF065679BD4CD17C0ULL) ^ aOUSaltD[(((511U - aIndex) + 356U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xE021F51C1A0F60F9ULL), 37U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0xB5275BEE4DDB865BULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0x78C8CC51174DAE0AULL) ^ aOUSaltB[((aIndex + 212U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x2AE1338C6BF55159ULL), 19U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x6BD19DE67ECE77D6ULL) + aOUSaltE[(((511U - aIndex) + 414U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xF4871DA082604098ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xBD83A74BB521911FULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x8B342A80F0A55340ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x1A1A8CE12510B29AULL) ^ aOUSaltC[(((511U - aIndex) + 99U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x1A32EAE56C2A2AABULL), 47U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0x0C67DC71B14C2AD7ULL) + aOUSaltF[((aIndex + 90U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x2FA6A1D45CBECAECULL;
