            //
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 48U) + RotL64(aOrbiterF, 20U)) + aOrbiterH);
            aWandererE = aWandererE + (((RotL64(aCross, 13U) + RotL64(aOrbiterB, 3U)) + aOrbiterJ) + aWUSaltG[(((511U - aIndex) + 423U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aIngress, 37U) + RotL64(aOrbiterJ, 29U)) + aOrbiterF) + RotL64(aCarry, 43U));
            aWandererC = aWandererC + (((RotL64(aScatter, 35U) + aOrbiterE) + RotL64(aOrbiterK, 23U)) + aWUSaltA[(((511U - aIndex) + 427U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 39U) + aOrbiterA) + RotL64(aOrbiterD, 11U));
            aWandererD = aWandererD + (((RotL64(aCross, 43U) + RotL64(aOrbiterK, 51U)) + aOrbiterB) + aWUSaltE[((aIndex + 325U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 57U) + RotL64(aOrbiterG, 5U)) + aOrbiterC) + aWUSaltC[((aIndex + 417U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aScatter, 26U) + aOrbiterH) + RotL64(aOrbiterG, 27U));
            aWandererH = aWandererH ^ ((((RotL64(aPrevious, 51U) + RotL64(aOrbiterC, 48U)) + aOrbiterI) + RotL64(aCarry, 27U)) + aWUSaltH[(((511U - aIndex) + 511U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aCross, 11U) + RotL64(aOrbiterI, 35U)) + aOrbiterA);
            aWandererG = aWandererG ^ ((RotL64(aIngress, 23U) + RotL64(aOrbiterD, 13U)) + aOrbiterE);
            //
            aCarry = aCarry + (RotL64(aWandererC, 60U) ^ aWandererD);
            aCarry = aCarry + (RotL64(aWandererI, 57U) ^ aWandererB);
            aCarry = aCarry + (RotL64(aWandererJ, 39U) ^ aWandererG);
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererK, 3U));
            aCarry = aCarry + (RotL64(aWandererA, 5U) ^ aWandererF);
            aCarry = aCarry + RotL64(aWandererE, 46U);
            aCarry = aCarry + RotL64(aIngress, 19U);
            aCarry = TwistMix64::DiffuseC(aCarry);
            //
            aFuseLaneD[S_BLOCK1 - aIndex] = aIngress;
